CREATE TYPE "OrderStatus" AS ENUM ('DRAFT', 'SENT', 'ACCEPTED', 'PREPARING', 'READY', 'SERVED', 'PAYMENT_REQUESTED', 'PAID', 'CANCELLED');
CREATE TYPE "TableStatus" AS ENUM ('FREE', 'ORDERING', 'SENT', 'PREPARING', 'READY', 'SERVED', 'PAYMENT_REQUESTED', 'PAID');
CREATE TYPE "PaymentMethod" AS ENUM ('CASH', 'CARD', 'OTHER');
CREATE TABLE "CafeTable" ("id" SERIAL NOT NULL, "number" INTEGER NOT NULL, "name" TEXT, "status" "TableStatus" NOT NULL DEFAULT 'FREE', "isActive" BOOLEAN NOT NULL DEFAULT true, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "CafeTable_pkey" PRIMARY KEY ("id"));
CREATE TABLE "MenuCategory" ("id" SERIAL NOT NULL, "name" TEXT NOT NULL, "sortOrder" INTEGER NOT NULL DEFAULT 0, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "MenuCategory_pkey" PRIMARY KEY ("id"));
CREATE TABLE "MenuItem" ("id" SERIAL NOT NULL, "name" TEXT NOT NULL, "description" TEXT, "price" INTEGER NOT NULL, "categoryId" INTEGER NOT NULL, "isActive" BOOLEAN NOT NULL DEFAULT true, "isAvailable" BOOLEAN NOT NULL DEFAULT true, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "MenuItem_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Waiter" ("id" SERIAL NOT NULL, "name" TEXT NOT NULL, "pin" TEXT, "isActive" BOOLEAN NOT NULL DEFAULT true, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Waiter_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Order" ("id" SERIAL NOT NULL, "tableId" INTEGER NOT NULL, "waiterId" INTEGER, "waiterName" TEXT NOT NULL, "status" "OrderStatus" NOT NULL DEFAULT 'DRAFT', "total" INTEGER NOT NULL DEFAULT 0, "paymentMethod" "PaymentMethod", "paidAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Order_pkey" PRIMARY KEY ("id"));
CREATE TABLE "OrderItem" ("id" SERIAL NOT NULL, "orderId" INTEGER NOT NULL, "menuItemId" INTEGER NOT NULL, "nameSnapshot" TEXT NOT NULL, "quantity" INTEGER NOT NULL DEFAULT 1, "unitPrice" INTEGER NOT NULL, "notes" TEXT NOT NULL DEFAULT '', "options" TEXT NOT NULL DEFAULT '[]', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "OrderItem_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "CafeTable_number_key" ON "CafeTable"("number");
CREATE UNIQUE INDEX "MenuCategory_name_key" ON "MenuCategory"("name");
ALTER TABLE "MenuItem" ADD CONSTRAINT "MenuItem_categoryId_fkey" FOREIGN KEY ("categoryId") REFERENCES "MenuCategory"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Order" ADD CONSTRAINT "Order_tableId_fkey" FOREIGN KEY ("tableId") REFERENCES "CafeTable"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "Order" ADD CONSTRAINT "Order_waiterId_fkey" FOREIGN KEY ("waiterId") REFERENCES "Waiter"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "OrderItem" ADD CONSTRAINT "OrderItem_orderId_fkey" FOREIGN KEY ("orderId") REFERENCES "Order"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "OrderItem" ADD CONSTRAINT "OrderItem_menuItemId_fkey" FOREIGN KEY ("menuItemId") REFERENCES "MenuItem"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
